def transform(grid):
    """Fill each enclosed zero region with a size-dependent color, retaining the 2 markers."""
    h, w = len(grid), len(grid[0])
    outside = set()
    queue = deque()

    # Flood-fill the zero background connected to any grid edge.
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in outside:
                outside.add((nr, nc))
                queue.append((nr, nc))

    # Separate enclosed regions. Their interior widths 3, 5, and 7 map to
    # colors 8, 4, and 3 respectively (floor(24 / interior width)).
    enclosed = {
        (r, c)
        for r in range(h)
        for c in range(w)
        if grid[r][c] == 0 and (r, c) not in outside
    }
    result = [row[:] for row in grid]
    while enclosed:
        start = enclosed.pop()
        component = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (nr, nc) in enclosed:
                    enclosed.remove((nr, nc))
                    component.add((nr, nc))
                    stack.append((nr, nc))
        min_r = min(r for r, _ in component)
        max_r = max(r for r, _ in component)
        min_c = min(c for _, c in component)
        max_c = max(c for _, c in component)
        interior_width = max(max_r - min_r + 1, max_c - min_c + 1)
        color = max(1, 24 // interior_width)
        for r, c in component:
            result[r][c] = color
    return result


